A \mathfrak {B}-algebra consists of

\mathsf {X} \colon  \mathsf {Set}

\mathsf {x} \colon  \mathsf {X}

\mathsf {x'} \colon  \mathsf {X}

A displayed \mathfrak {B}-algebra 
(over a \mathfrak {B}-algebra (\mathsf {X}, \mathsf {x}, \mathsf {x'}))
consists of

\mathsf {X}{}^{\mathsf  D} \colon  \mathsf {X} \to  \mathsf {Set}

\mathsf {x}{}^{\mathsf  D} \colon  \mathsf {X}{}^{\mathsf  D}\;\mathsf {x}

\mathsf {x'}{}^{\mathsf  D} \colon  \mathsf {X}{}^{\mathsf  D}\;\mathsf {x'}

A section of a displayed \mathfrak {B}-algebra (\mathsf {X}{}^{\mathsf  D}, \mathsf {x}{}^{\mathsf  D}, \mathsf {x'}{}^{\mathsf  D}) (over a \mathfrak {B}-algebra (\mathsf {X}, \mathsf {x}, \mathsf {x'}))
consists of

\mathsf {X}{}^{\mathsf  S} \colon  \lparen {}z \colon  \mathsf {X}\rparen {}  \to  \mathsf {X}{}^{\mathsf  D}\;z

\mathsf {x}{}^{\mathsf  S} \colon  \mathsf {X}{}^{\mathsf  S}\;\mathsf {x}\;=\;\mathsf {x}{}^{\mathsf  D}

\mathsf {x'}{}^{\mathsf  S} \colon  \mathsf {X}{}^{\mathsf  S}\;\mathsf {x'}\;=\;\mathsf {x'}{}^{\mathsf  D}

The GAT \mathfrak {P} is given by the signature




\mathsf {U}

\mathsf {El}\;0

A \mathfrak {P}-algebra consists of

\mathsf {X} \colon  \mathsf {Set}

\mathsf {x} \colon  \mathsf {X}

A displayed \mathfrak {P}-algebra 
(over a \mathfrak {P}-algebra (\mathsf {X}, \mathsf {x}))
consists of

\mathsf {X}{}^{\mathsf  D} \colon  \mathsf {X} \to  \mathsf {Set}

\mathsf {x}{}^{\mathsf  D} \colon  \mathsf {X}{}^{\mathsf  D}\;\mathsf {x}

A section of a displayed \mathfrak {P}-algebra (\mathsf {X}{}^{\mathsf D}, \mathsf {x}{}^{\mathsf D}) (over a \mathfrak {P}-algebra (\mathsf {X}, \mathsf {x})) consists of
\mathsf {X}{}^{\mathsf S} \colon \lparen {}z \colon \mathsf {X}\rparen {} \to \mathsf {X}{}^{\mathsf D}\;z
\mathsf {x}{}^{\mathsf S} \colon \mathsf {X}{}^{\mathsf S}\;\mathsf {x}\;=\;\mathsf {x}{}^{\mathsf D}

A \mathfrak {B}-algebra consists of

\mathsf {X} \colon  \mathsf {Set}

\mathsf {x} \colon  \mathsf {X}

\mathsf {x'} \colon  \mathsf {X}

A displayed \mathfrak {B}-algebra 
(over a \mathfrak {B}-algebra (\mathsf {X}, \mathsf {x}, \mathsf {x'}))
consists of

\mathsf {X}{}^{\mathsf  D} \colon  \mathsf {X} \to  \mathsf {Set}

\mathsf {x}{}^{\mathsf  D} \colon  \mathsf {X}{}^{\mathsf  D}\;\mathsf {x}

\mathsf {x'}{}^{\mathsf  D} \colon  \mathsf {X}{}^{\mathsf  D}\;\mathsf {x'}

A section of a displayed \mathfrak {B}-algebra (\mathsf {X}{}^{\mathsf  D}, \mathsf {x}{}^{\mathsf  D}, \mathsf {x'}{}^{\mathsf  D}) (over a \mathfrak {B}-algebra (\mathsf {X}, \mathsf {x}, \mathsf {x'}))
consists of

\mathsf {X}{}^{\mathsf  S} \colon  \lparen {}z \colon  \mathsf {X}\rparen {}  \to  \mathsf {X}{}^{\mathsf  D}\;z

\mathsf {x}{}^{\mathsf  S} \colon  \mathsf {X}{}^{\mathsf  S}\;\mathsf {x}\;=\;\mathsf {x}{}^{\mathsf  D}

\mathsf {x'}{}^{\mathsf  S} \colon  \mathsf {X}{}^{\mathsf  S}\;\mathsf {x'}\;=\;\mathsf {x'}{}^{\mathsf  D}

The GAT \mathfrak {N} is given by the signature




\mathsf {U}

\mathsf {El}\;0

\Pi \;1\;\lparen {}\mathsf {El}\;2\rparen {}

A \mathfrak {N}-algebra consists of

\mathsf {N} \colon  \mathsf {Set}

\mathsf {z} \colon  \mathsf {N}

\mathsf {s} \colon  \mathsf {N} \to  \mathsf {N}

A displayed \mathfrak {N}-algebra 
(over a \mathfrak {N}-algebra (\mathsf {N}, \mathsf {z}, \mathsf {s}))
consists of

\mathsf {N}{}^{\mathsf  D} \colon  \mathsf {N} \to  \mathsf {Set}

\mathsf {z}{}^{\mathsf  D} \colon  \mathsf {N}{}^{\mathsf  D}\;\mathsf {z}

\mathsf {s}{}^{\mathsf  D} \colon  \{n \colon  \mathsf {N}\} \lparen {}ih \colon  \mathsf {N}{}^{\mathsf  D}\;n\rparen {}  \to  \mathsf {N}{}^{\mathsf  D}\;\lparen {}\mathsf {s}\;n\rparen {}

A section of a displayed \mathfrak {N}-algebra (\mathsf {N}{}^{\mathsf  D}, \mathsf {z}{}^{\mathsf  D}, \mathsf {s}{}^{\mathsf  D}) (over a \mathfrak {N}-algebra (\mathsf {N}, \mathsf {z}, \mathsf {s}))
consists of

\mathsf {N}{}^{\mathsf  S} \colon  \lparen {}n \colon  \mathsf {N}\rparen {}  \to  \mathsf {N}{}^{\mathsf  D}\;n

\mathsf {z}{}^{\mathsf  S} \colon  \mathsf {N}{}^{\mathsf  S}\;\mathsf {z}\;=\;\mathsf {z}{}^{\mathsf  D}

\mathsf {s}{}^{\mathsf  S} \colon  \{n \colon  \mathsf {N}\}  \to  \mathsf {N}{}^{\mathsf  S}\;\lparen {}\mathsf {s}\;n\rparen {}\;=\;\mathsf {s}{}^{\mathsf  D}\;\lparen {}\mathsf {N}{}^{\mathsf  S}\;n\rparen {}

The GAT \mathfrak {EO} is given by the signature




\mathsf {U}

\mathsf {U}

\mathsf {El}\;1

\Pi \;2\;\lparen {}\mathsf {El}\;2\rparen {}

\Pi \;2\;\lparen {}\mathsf {El}\;4\rparen {}

A \mathfrak {EO}-algebra consists of

\mathsf {Even} \colon  \mathsf {Set}

\mathsf {Odd} \colon  \mathsf {Set}

\mathsf {zero} \colon  \mathsf {Even}

\mathsf {succ} \colon  \mathsf {Even} \to  \mathsf {Odd}

\mathsf {succ'} \colon  \mathsf {Odd} \to  \mathsf {Even}

A homomorphism of \mathfrak {EO}-algebras (from (\mathsf {Even}_0, \mathsf {Odd}_0, \mathsf {zero}_0, \ldots ) to (\mathsf {Even}_1, \mathsf {Odd}_1, \mathsf {zero}_1, \ldots )) consists of
\mathsf {Even}{}^{\mathsf M} \colon \mathsf {Even}_0 \to \mathsf {Even}_1
\mathsf {Odd}{}^{\mathsf M} \colon \mathsf {Odd}_0 \to \mathsf {Odd}_1
\mathsf {zero}{}^{\mathsf M} \colon \mathsf {Even}{}^{\mathsf M}\;\mathsf {zero}_0\;=\;\mathsf {zero}_1
\mathsf {succ}{}^{\mathsf M} \colon \{n \colon \mathsf {Even}_0\} \to \mathsf {Odd}{}^{\mathsf M}\;\lparen {}\mathsf {succ}_0\;n\rparen {}\;=\;\mathsf {succ}_1\;\lparen {}\mathsf {Even}{}^{\mathsf M}\;n\rparen {}
\mathsf {succ'}{}^{\mathsf M} \colon \{n \colon \mathsf {Odd}_0\} \to \mathsf {Even}{}^{\mathsf M}\;\lparen {}\mathsf {succ'}_0\;n\rparen {}\;=\;\mathsf {succ'}_1\;\lparen {}\mathsf {Odd}{}^{\mathsf M}\;n\rparen {}

A displayed \mathfrak {EO}-algebra 
(over a \mathfrak {EO}-algebra (\mathsf {Even}, \mathsf {Odd}, \mathsf {zero}, \ldots ))
consists of

\mathsf {Even}{}^{\mathsf  D} \colon  \mathsf {Even} \to  \mathsf {Set}

\mathsf {Odd}{}^{\mathsf  D} \colon  \mathsf {Odd} \to  \mathsf {Set}

\mathsf {zero}{}^{\mathsf  D} \colon  \mathsf {Even}{}^{\mathsf  D}\;\mathsf {zero}

\mathsf {succ}{}^{\mathsf  D} \colon  \{n \colon  \mathsf {Even}\} \lparen {}ih \colon  \mathsf {Even}{}^{\mathsf  D}\;n\rparen {}  \to  \mathsf {Odd}{}^{\mathsf  D}\;\lparen {}\mathsf {succ}\;n\rparen {}

\mathsf {succ'}{}^{\mathsf  D} \colon  \{n \colon  \mathsf {Odd}\} \lparen {}ih \colon  \mathsf {Odd}{}^{\mathsf  D}\;n\rparen {}  \to  \mathsf {Even}{}^{\mathsf  D}\;\lparen {}\mathsf {succ'}\;n\rparen {}

A section of a displayed \mathfrak {EO}-algebra (\mathsf {Even}{}^{\mathsf  D}, \mathsf {Odd}{}^{\mathsf  D}, \mathsf {zero}{}^{\mathsf  D}, \ldots ) (over a \mathfrak {EO}-algebra (\mathsf {Even}, \mathsf {Odd}, \mathsf {zero}, \ldots ))
consists of

\mathsf {Even}{}^{\mathsf  S} \colon  \lparen {}n \colon  \mathsf {Even}\rparen {}  \to  \mathsf {Even}{}^{\mathsf  D}\;n

\mathsf {Odd}{}^{\mathsf  S} \colon  \lparen {}n \colon  \mathsf {Odd}\rparen {}  \to  \mathsf {Odd}{}^{\mathsf  D}\;n

\mathsf {zero}{}^{\mathsf  S} \colon  \mathsf {Even}{}^{\mathsf  S}\;\mathsf {zero}\;=\;\mathsf {zero}{}^{\mathsf  D}

\mathsf {succ}{}^{\mathsf  S} \colon  \{n \colon  \mathsf {Even}\}  \to  \mathsf {Odd}{}^{\mathsf  S}\;\lparen {}\mathsf {succ}\;n\rparen {}\;=\;\mathsf {succ}{}^{\mathsf  D}\;\lparen {}\mathsf {Even}{}^{\mathsf  S}\;n\rparen {}

\mathsf {succ'}{}^{\mathsf  S} \colon  \{n \colon  \mathsf {Odd}\}  \to  \mathsf {Even}{}^{\mathsf  S}\;\lparen {}\mathsf {succ'}\;n\rparen {}\;=\;\mathsf {succ'}{}^{\mathsf  D}\;\lparen {}\mathsf {Odd}{}^{\mathsf  S}\;n\rparen {}
